import test from 'node:test';
import fs from 'node:fs';
import path from 'node:path';
import vm from 'node:vm';
import { createRequire, register } from 'node:module';
import { pathToFileURL } from 'node:url';
import { randomUUID, createHash } from 'node:crypto';
const root=process.cwd(), require=createRequire(path.join(root,'package.json'));
const ts=require('typescript');
register(pathToFileURL(path.join(root,'scripts/lib/ts-esm-loader.mjs')));
const mod=rel=>import(pathToFileURL(path.join(root,rel)).href);
const {packetTestDatabase,readPacketCatalog}=await mod('scripts/rcap-packet-database-reference.mjs');
const {REPAIR_PATH,CONTRACT_PATH,comparePacketCatalog}=await mod('scripts/rcap-packet-database-contract.mjs');
const {migrationCertification,acceptanceLedgerExecution}=await mod('scripts/rcap-migration-certification.mjs');
const source=fs.readFileSync(path.join(root,'scripts/rcap-hosted-acceptance-migrate.mjs'),'utf8');
const loop=source.slice(source.indexOf('  let satisfied = 0;'),source.indexOf('\n  record(\n    "authorized_sequence_applied_in_order"'));
async function runCurrentLoop({ledgerMatch=false,ledgerWriteOk=true,applyOk=true}={}) {
  const hash='a'.repeat(64),calls=[];
  const context={sequence:[{phase:51,path:'phase-51.sql',authorizationId:'review'}],
    evidence:{authorizedSequence:[{phase:51,onDisk:hash}]},
    ledger:new Map(ledgerMatch?[[51,{sha256:hash,applied_by:'hosted_acceptance_pipeline'}]]:[]),
    migrationCertification,acceptanceLedgerExecution,rootDir:root,path,
    fs:{readFileSync(){return 'APPLY_FIXTURE';}},console:{log(){}},
    query:async query=>{calls.push(query);return query==='APPLY_FIXTURE'
      ? {ok:applyOk,status:applyOk?201:409,json:applyOk?[]:{message:'42710: duplicate object'}}
      : {ok:ledgerWriteOk,status:ledgerWriteOk?201:503,json:ledgerWriteOk?[]:{message:'ledger unavailable'}};}};
  const result=await vm.runInNewContext(`(async()=>{${loop}\nreturn {satisfied,failure,evidence};})()`,context);
  return {...result,calls};
}
test('CURRENT counterexample: unsuccessful ledger write is counted as satisfied',async()=>{
  const r=await runCurrentLoop({ledgerWriteOk:false});
  assert.equal(r.satisfied,1);assert.equal(r.failure,null);assert.equal(r.calls.length,2);
});
test('CURRENT counterexample: matching non-Phase-50 receipt skips all live postconditions',async()=>{
  const r=await runCurrentLoop({ledgerMatch:true});
  assert.equal(r.satisfied,1);assert.equal(r.calls.length,0);
});
test('CURRENT corrected branch: duplicate apply response no longer certifies whole phase',async()=>{
  const r=await runCurrentLoop({applyOk:false});
  assert.equal(r.satisfied,0);assert.match(r.failure,/duplicate object/);assert.equal(r.calls.length,1);
});
function functionsFrom(rel,names,context) {
  const input=fs.readFileSync(path.join(root,rel),'utf8');
  const ast=ts.createSourceFile(rel,input,ts.ScriptTarget.Latest,true);
  const selected=ast.statements.filter(n=>ts.isFunctionDeclaration(n)&&names.includes(n.name?.text));
  assert.equal(selected.length,names.length);
  const code=ts.transpileModule(selected.map(n=>n.getText(ast).replace(/^export /,'')).join('\n'),{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022}}).outputText;
  vm.runInNewContext(code+'\nglobalThis.reviewFunctions={'+names.join(',')+'};',context);
  return context.reviewFunctions;
}
