  db.sql(`insert into partner_records values ('${partner}','review'); insert into rcap_persons values ('${person}','review','review');
    insert into partner_packet_entitlement(partner_id,packet_cap) values ('${partner}',10);
    insert into rcap_document_packets values ('${packet}');
    select set_config('rcap.packet_mutation_authority','enqueue_packet_render_job',false);
    insert into packet_render_jobs(id,packet_id,route_id,renderer_kind,renderer_version,profile_id,profile_version,input_hash,partner_id,person_id,matter_id)
    values ('${job}','${packet}','MS:review','packet_document_v1','1.0.0','MS','review','${'1'.repeat(64)}','${partner}','${person}','${matter}');`);
  const claim=db.json("select to_jsonb(c) from claim_packet_render_job('review',null,600) c");
  const {PDFDocument}=require('pdf-lib');const pdf=await PDFDocument.create();pdf.addPage([612,792]);const bytes=Buffer.from(await pdf.save());
  const sha=createHash('sha256').update(bytes).digest('hex'),objectPath=`packets/${packet}/${sha}.pdf`;
  db.sql(`select start_packet_render('${job}','${claim.fencing_token}'); select start_packet_validation('${job}','${claim.fencing_token}');
    select * from finalize_packet_render_job('${job}','${claim.fencing_token}','${objectPath}','${sha}','${sha}','${sha}','${sha}',${bytes.length},1,'sha256:${'a'.repeat(64)}');`);
  assert.equal(db.scalar(`select status from packet_render_jobs where id='${job}'`),'artifact_validated');
  const errors=[],queries=[];
  const client={from(table){let fields,filter;return {select(f){fields=f;return this;},eq(k,v){assert.equal(k,'id');assert.match(v,/^[a-f0-9-]{36}$/);filter=v;return this;},async maybeSingle(){
    const q=`select to_jsonb(r) from (select ${fields} from public.${table} where id='${filter}') r`;queries.push(q);
    const result=await db.sqlAsync(q);if(!result.ok){errors.push(result.err);return {data:null,error:{message:result.err}};}
    return {data:result.out?JSON.parse(result.out):null,error:null};}}};
  const {getRenderJob}=functionsFrom('src/lib/rcap/render/job-queue.ts',['rowFromRecord','getRenderJob'],{getSupabaseAdminClient:()=>client});
  assert.equal(await getRenderJob(job),null);assert.match(errors[0],/sponsored_consumer_auth_user_id.*does not exist/);
  const {authorizePacketDownload,streamAuthorizedPacket}=await mod('src/lib/rcap/render/packet-delivery.ts');
  let storageReads=0;
  const {GET}=functionsFrom('src/app/api/rcap/packets/[jobId]/download/route.ts',['GET'],{
    getRcapBriefcaseAuthState:async()=>({isAuthenticated:true,userId:randomUUID()}),
    getPacketArtifactStorage:()=>({read:async()=>{storageReads++;return bytes;}}),getRenderJob,
    resolveConsumerDeliveryAccess:()=>({allowed:true}),getBriefcaseItem:async()=>({id:randomUUID()}),
    requireCurrentPacketVerification:async()=>{throw new Error('unexpected downstream call');},
    consumerMatterIdForItem:()=>matter,recordDeliveryEvent:async()=>null,
    authorizePacketDownload,streamAuthorizedPacket,NextResponse:require('next/server').NextResponse
  });
  const response=await GET(new Request('http://local.invalid/download'),{params:Promise.resolve({jobId:job})});
  assert.equal(response.status,404);assert.equal((await response.json()).code,'not_found');assert.equal(storageReads,0);
  assert.equal(queries.length,2);assert.equal(errors.length,2);
});

